import { Ionicons } from "@expo/vector-icons";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useState } from "react";
import { ActivityIndicator, Platform, Pressable, Share, StyleSheet, Text, useWindowDimensions, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { formatMinor } from "../../ui/money";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { useCurrentUser } from "../auth/use-current-user";
import { getVendorReport } from "./vendor.api";

const periods = [7, 30, 90, 365] as const;
export function VendorReportsScreen() {
  const router = useRouter();
  const compact = useWindowDimensions().width < 620;
  const user = useCurrentUser();
  const [days, setDays] = useState<(typeof periods)[number]>(30);
  const report = useQuery({ queryKey: ["vendor", "report", user?.uid, days], queryFn: () => getVendorReport(user!, days), enabled: Boolean(user) });

  const exportCsv = async () => {
    if (!report.data) return;
    const rows: Array<Array<string | number>> = [["Metric", "Value"], ["Period days", report.data.periodDays], ["Delivered sales minor", report.data.grossSalesMinor], ["Orders", report.data.orderCount], ["Delivered", report.data.deliveredCount], ["Cancelled", report.data.cancelledCount], ["Returns", report.data.returnCount], ["Average order minor", report.data.averageOrderMinor], ["Fulfilment rate", report.data.fulfilmentRate], ["Products", report.data.productCount], ["Low-stock variants", report.data.lowStockCount], [], ["Order number", "Shop", "Items", "Status", "Total minor", "Created at"], ...report.data.recentOrders.map((order) => [order.orderNumber, order.shopName, order.itemCount, order.status, order.totalMinor, order.createdAt])];
    const csv = rows.map((row) => row.map((cell) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    if (Platform.OS === "web") { const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = `amiyo-seller-report-${days}d.csv`; link.click(); URL.revokeObjectURL(url); }
    else await Share.share({ title: "Amiyo seller report", message: csv });
  };

  return <Screen eyebrow="SELLER CENTER" title="Analytics & reports" description="Track sales, fulfilment, returns and stock health from live seller data.">
    <View style={[styles.toolbar, compact && styles.toolbarCompact]}><View style={styles.periods}>{periods.map((period) => <Pressable key={period} onPress={() => setDays(period)} style={[styles.period, days === period && styles.activePeriod]}><Text style={[styles.periodText, days === period && styles.activePeriodText]}>{period === 365 ? "1 year" : `${period} days`}</Text></Pressable>)}</View><Pressable accessibilityRole="button" disabled={!report.data} onPress={exportCsv} style={[styles.export, compact && styles.exportCompact, !report.data && styles.disabled]}><Ionicons color={colors.background} name="download-outline" size={17} /><Text style={styles.exportText}>{Platform.OS === "web" ? "Download CSV" : "Share CSV"}</Text></Pressable></View>
    {report.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{report.error ? <Text accessibilityRole="alert" style={styles.error}>{report.error.message}</Text> : null}
    {report.data ? <>
      <View style={[styles.hero, compact && styles.heroCompact]}><View style={styles.heroCopy}><Text style={styles.heroEyebrow}>DELIVERED REVENUE</Text><Text adjustsFontSizeToFit numberOfLines={1} style={styles.heroValue}>{formatMinor(report.data.grossSalesMinor)}</Text><Text style={styles.heroText}>Confirmed sales for the selected {report.data.periodDays}-day period.</Text></View><View style={styles.health}><Text style={styles.healthValue}>{report.data.fulfilmentRate}%</Text><Text style={styles.healthLabel}>fulfilment rate</Text></View></View>
      <View style={styles.metrics}><Metric compact={compact} label="Orders" value={String(report.data.orderCount)} /><Metric compact={compact} label="Average order" value={formatMinor(report.data.averageOrderMinor)} /><Metric compact={compact} label="Products" value={String(report.data.productCount)} /><Metric compact={compact} label="Low stock" value={String(report.data.lowStockCount)} /></View>
      <View style={[styles.grid, compact && styles.gridCompact]}><ModuleCard title="Order performance" meta={`Last ${report.data.periodDays} days`}><Stat label="Delivered" value={report.data.deliveredCount} tone={colors.success} /><Stat label="Cancelled" value={report.data.cancelledCount} tone={colors.danger} /><Stat label="Returns" value={report.data.returnCount} tone={colors.warning} /></ModuleCard><ModuleCard title="Catalog health" meta="Current sellable inventory"><Stat label="Active products" value={report.data.productCount} tone={colors.primary} /><Stat label="Low-stock variants" value={report.data.lowStockCount} tone={colors.warning} /></ModuleCard></View>
      <ModuleCard title="Order status breakdown" meta="Operational pipeline">{Object.entries(report.data.statusCounts).length ? Object.entries(report.data.statusCounts).map(([status, count]) => <View key={status} style={[styles.statusRow, compact && styles.statusRowCompact]}><Text style={styles.status}>{status.replaceAll("_", " ")}</Text><View style={styles.track}><View style={[styles.fill, { width: `${Math.max(4, (count / Math.max(1, report.data.orderCount)) * 100)}%` }]} /></View><Text style={styles.count}>{count}</Text></View>) : <Text style={styles.muted}>No orders in this period.</Text>}</ModuleCard>
      <ModuleCard title="Recent orders" meta="Latest activity in selected period">{report.data.recentOrders.map((order) => <Pressable accessibilityRole="link" key={order.id} onPress={() => router.push(`/vendor/orders/${order.id}` as never)} style={({ pressed }) => [styles.order, compact && styles.orderCompact, pressed && styles.pressed]}><View style={styles.orderIdentity}><Text style={styles.orderId}>{order.orderNumber}</Text><Text style={styles.muted}>{order.shopName} · {order.itemCount} item{order.itemCount === 1 ? "" : "s"} · {new Date(order.createdAt).toLocaleString("en-BD")}</Text></View><Text style={[styles.orderStatus, compact && styles.orderStatusCompact]}>{order.status.replaceAll("_", " ")}</Text><View style={styles.orderAmount}><Text style={styles.orderValue}>{formatMinor(order.totalMinor)}</Text><Ionicons color={colors.primary} name="chevron-forward" size={17} /></View></Pressable>)}{!report.data.recentOrders.length ? <Text style={styles.muted}>No recent orders.</Text> : null}</ModuleCard>
    </> : null}
  </Screen>;
}

function Metric({ compact, label, value }: { compact: boolean; label: string; value: string }) { return <View style={[styles.metric, compact && styles.metricCompact]}><Text adjustsFontSizeToFit numberOfLines={1} style={styles.metricValue}>{value}</Text><Text style={styles.muted}>{label}</Text></View>; }
function Stat({ label, tone, value }: { label: string; tone: string; value: number }) { return <View style={styles.stat}><Text style={styles.muted}>{label}</Text><Text style={[styles.statValue, { color: tone }]}>{value}</Text></View>; }

const styles = StyleSheet.create({
  toolbar: { alignItems: "center", flexDirection: "row", gap: spacing.md, justifyContent: "space-between" }, toolbarCompact: { alignItems: "stretch", flexDirection: "column" }, periods: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, period: { backgroundColor: colors.surface, borderRadius: radius.pill, paddingHorizontal: 14, paddingVertical: 9 }, activePeriod: { backgroundColor: colors.primary }, periodText: { color: colors.text, fontSize: 12, fontWeight: "600" }, activePeriodText: { color: colors.background }, export: { alignItems: "center", backgroundColor: colors.navy, borderRadius: radius.pill, flexDirection: "row", gap: 6, paddingHorizontal: 16, paddingVertical: 10 }, exportCompact: { justifyContent: "center", width: "100%" }, exportText: { color: colors.background, fontSize: 12, fontWeight: "700" }, disabled: { opacity: 0.45 },
  hero: { alignItems: "center", backgroundColor: colors.navy, borderRadius: radius.xl, flexDirection: "row", gap: spacing.lg, justifyContent: "space-between", padding: spacing.xl }, heroCompact: { alignItems: "flex-start", flexDirection: "column", padding: spacing.lg }, heroCopy: { flex: 1, gap: 5 }, heroEyebrow: { color: colors.accent, fontSize: 10, fontWeight: "700", letterSpacing: 1.2 }, heroValue: { color: colors.background, fontSize: 34, fontWeight: "700" }, heroText: { color: colors.background, fontSize: 12, opacity: 0.78 }, health: { alignItems: "flex-end", backgroundColor: colors.accentSoft, borderRadius: radius.lg, minWidth: 130, padding: spacing.md }, healthValue: { color: colors.success, fontSize: 27, fontWeight: "700" }, healthLabel: { color: colors.navy, fontSize: 11, fontWeight: "600" },
  metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, metric: { backgroundColor: colors.primarySoft, borderRadius: radius.lg, flex: 1, minWidth: 140, padding: spacing.md }, metricCompact: { minWidth: "45%" }, metricValue: { color: colors.primary, fontSize: 24, fontWeight: "700" }, muted: { color: colors.muted, fontSize: 12 }, grid: { flexDirection: "row", gap: spacing.md }, gridCompact: { flexDirection: "column" }, stat: { alignItems: "center", backgroundColor: colors.background, borderRadius: radius.md, flexDirection: "row", justifyContent: "space-between", padding: spacing.sm }, statValue: { fontSize: 18, fontWeight: "700" }, statusRow: { alignItems: "center", flexDirection: "row", gap: spacing.sm }, statusRowCompact: { alignItems: "stretch", flexWrap: "wrap" }, status: { color: colors.text, fontSize: 11, fontWeight: "600", width: 105 }, track: { backgroundColor: colors.accentSoft, borderRadius: radius.pill, flex: 1, height: 9, minWidth: 90, overflow: "hidden" }, fill: { backgroundColor: colors.primary, borderRadius: radius.pill, height: 9 }, count: { color: colors.text, fontWeight: "700", textAlign: "right", width: 28 }, order: { alignItems: "center", backgroundColor: colors.background, borderRadius: radius.md, flexDirection: "row", gap: spacing.md, justifyContent: "space-between", padding: spacing.md }, orderCompact: { alignItems: "flex-start", flexDirection: "column", gap: spacing.xs }, orderIdentity: { flex: 1, minWidth: 0 }, orderId: { color: colors.text, fontWeight: "700" }, orderStatus: { color: colors.primary, flex: 1, fontSize: 11, fontWeight: "700", textAlign: "center", textTransform: "uppercase" }, orderStatusCompact: { flex: 0, textAlign: "left" }, orderAmount: { alignItems: "center", flexDirection: "row", gap: spacing.xs }, orderValue: { color: colors.text, fontWeight: "700" }, pressed: { opacity: 0.76, transform: [{ scale: 0.995 }] }, error: { color: colors.danger }
});
